import React, { useEffect, useState } from 'react';
import { getStats, deleteUser } from '../services/adminService';
import { getRequests } from '../services/requestService';
import { getUsers } from '../services/adminService';
import { Line, Doughnut } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, ArcElement } from 'chart.js';
import { toast } from 'react-toastify';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, ArcElement);

const AdminDashboard = () => {
  const [stats, setStats] = useState({});
  const [recentRequests, setRecentRequests] = useState([]);
  const [recentUsers, setRecentUsers] = useState([]);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const statsData = await getStats();
      setStats(statsData);
      const requests = await getRequests();
      setRecentRequests(requests.slice(0, 5));
      const users = await getUsers();
      setRecentUsers(users.slice(0, 5));
    } catch (error) {
      toast.error('Erreur chargement dashboard admin');
    }
  };

  const handleDeleteUser = async (user) => {
    const confirmed = window.confirm(`Supprimer l utilisateur ${user.fullName} ?`);
    if (!confirmed) return;

    try {
      await deleteUser(user.id);
      toast.success('Utilisateur supprimé');
      await loadData();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Erreur lors de la suppression');
    }
  };

  const lineData = {
    labels: ['Jan', 'Fév', 'Mar', 'Avr', 'Mai', 'Juin'],
    datasets: [
      { label: 'Demandes créées', data: [12, 19, 15, 17, 22, 25], borderColor: 'rgb(59,130,246)', tension: 0.1 },
    ],
  };

  const doughnutData = {
    labels: ['Approuvées', 'Rejetées', 'En cours'],
    datasets: [{ data: [45, 12, 30], backgroundColor: ['#10b981', '#ef4444', '#f59e0b'] }],
  };

  return (
    <div>
      <h1 className="text-3xl font-bold mb-6 tracking-tight">Tableau de bord Admin</h1>
      
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <div className="card">
          <h3 className="text-slate-500 mb-1">Utilisateurs</h3>
          <p className="text-3xl font-bold">{stats.totalUsers || 0}</p>
        </div>
        <div className="card">
          <h3 className="text-slate-500 mb-1">Demandes en attente</h3>
          <p className="text-3xl font-bold">{stats.pendingRequests || 0}</p>
        </div>
        <div className="card">
          <h3 className="text-slate-500 mb-1">Demandes en cours</h3>
          <p className="text-3xl font-bold">{stats.inProgressRequests || 0}</p>
        </div>
        <div className="card">
          <h3 className="text-slate-500 mb-1">Terminées</h3>
          <p className="text-3xl font-bold">{stats.completedRequests || 0}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
        <div className="card">
          <h2 className="font-bold mb-4">Évolution des demandes</h2>
          <Line data={lineData} />
        </div>
        <div className="card">
          <h2 className="font-bold mb-4">Répartition des statuts</h2>
          <Doughnut data={doughnutData} />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="card">
          <h2 className="font-bold mb-4">Dernières demandes</h2>
          <table>
            <thead>
              <tr><th>Réf.</th><th>Type</th><th>Statut</th></tr>
            </thead>
            <tbody>
              {recentRequests.map(req => (
                <tr key={req.id}>
                  <td>{req.reference}</td>
                  <td>{req.workflowType}</td>
                  <td><span className={`status status-${req.status}`}>{req.status}</span></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="card">
          <h2 className="font-bold mb-4">Derniers utilisateurs</h2>
          <table>
            <thead><tr><th>Nom</th><th>Email</th><th>Rôle</th><th>Action</th></tr></thead>
            <tbody>
              {recentUsers.map(user => (
                <tr key={user.id}>
                  <td>{user.fullName}</td>
                  <td>{user.email}</td>
                  <td>{user.role}</td>
                  <td>
                    <button
                      onClick={() => handleDeleteUser(user)}
                      className="btn btn-danger text-xs"
                    >
                      Supprimer
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
